const entrada = $input.first().json;

// Obtém o CSV do campo correto
const csv = entrada.data;

if (typeof csv !== 'string' || csv.trim() === '') {
  throw new Error(
    'O campo "data" não foi encontrado ou não contém texto CSV. ' +
    'Verifique o JSON de entrada do nó anterior.'
  );
}

// Divide o CSV em linhas e remove linhas vazias
const linhas = csv
  .trim()
  .split(/\r?\n/)
  .filter(linha => linha.trim() !== '');

// Extrai os cabeçalhos
const cabecalhos = linhas[0]
  .split(',')
  .map(campo => campo.trim());

// Verifica se existem dados além do cabeçalho
if (linhas.length < 2) {
  throw new Error('O CSV contém apenas o cabeçalho, sem registros.');
}

// Transforma cada linha em um item individual do n8n
const resultado = linhas.slice(1).map(linha => {
  const valores = linha.split(',').map(valor => valor.trim());

  const registro = Object.fromEntries(
    cabecalhos.map((campo, indice) => [
      campo,
      valores[indice] ?? ''
    ])
  );

  // Converte minimo para número
  const minimoTexto = String(registro.minimo)
    .replace(',', '.');

  registro.minimo = Number(minimoTexto);

  if (!Number.isFinite(registro.minimo)) {
    throw new Error(
      `Valor inválido no campo minimo: ${registro.minimo}`
    );
  }

  return {
    json: registro
  };
});

return resultado;

// 1. Pega a lista de clientes dentro de body.clientes (no primeiro item)
const clientes = $input.all()[0].json.body.clientes;

// 2. Pega todos os produtos de investimentos que vieram do CSV
const investimentos = $input.all().map(item => item.json);

// 3. Gera a mensagem personalizada para cada cliente
return clientes.map(cliente => {
  // Filtra apenas os investimentos compatíveis com o perfil do cliente
  const opcoesCompativeis = investimentos.filter(inv => {
    return inv.perfil && inv.perfil.toLowerCase() === cliente.perfil.toLowerCase();
  });

  // Monta a lista formatada dos produtos
  const listaProdutos = opcoesCompativeis
    .map(inv => `- ${inv.produto} (Aplicação mínima: R$ ${inv.minimo} | Rentabilidade: ${inv.rentabilidade})`)
    .join('\n');

  // Garante a formatação do saldo
  const saldoFormatado = cliente.saldo.includes('R$') 
    ? cliente.saldo 
    : `R$ ${cliente.saldo}`;

  // Monta a mensagem final personalizada
  const mensagem = `Olá, ${cliente.nome}!

Identificamos que seu perfil de investidor é ${cliente.perfil}. Com base no seu saldo disponível de ${saldoFormatado}, selecionamos as seguintes opções recomendadas:

${listaProdutos}

Conte com a gente para alcançar seus objetivos financeiros!`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      mensagem: mensagem
    }
  };
});

// Processa cada cliente que veio do nó anterior
return $input.all().map(item => {
  const dados = item.json;

  // Monta uma lista simples e limpa das opções (caso ainda não esteja em texto)
  const produtosTexto = Array.isArray(dados.produtos)
    ? dados.produtos.map(p => `- ${p.produto} (Mínimo: R$ ${p.minimo}, Rentabilidade: ${p.rentabilidade})`).join('\n')
    : dados.mensagem; // Ou aproveita o resumo já gerado

  // Cria o prompt limpo com instruções claras para a IA
  const promptParaLLM = `Você é um assessor de investimentos sênior e atencioso.
Escreva uma mensagem personalizada e humanizada para o seguinte cliente:

- Nome: ${dados.nome}
- Perfil de investidor: ${dados.perfil}
- Saldo disponível: ${dados.saldo}

Opções de investimento recomendadas para o perfil dele:
${produtosTexto}

Diretrizes:
- Use um tom profissional, acolhedor e encorajador.
- Destaque por que essas opções combinam com o perfil ${dados.perfil}.
- Não prometa rentabilidade garantida onde houver risco.
- Mantenha a mensagem direta e objetiva (máximo 2 parágrafos).`;

  return {
    json: {
      nome: dados.nome,
      email: dados.email,
      perfil: dados.perfil,
      prompt: promptParaLLM
    }
  };
});

// Obtém os itens que saíram do nó do Gemini
const itens = $input.all();

return itens.map((item, index) => {
  const dados = item.json;

  // 1. Obtém o texto gerado pelo Gemini (cobre os nomes mais comuns)
  const textoIA = dados.text || dados.response || (dados.message && dados.message.content) || dados.prompt;

  // 2. Obtém os dados do cliente (se o Gemini manteve os campos ou se precisamos buscar do nó anterior)
  // Caso o nó do Gemini só tenha devolvido o texto, substitua 'Code' pelo nome do nó anterior
  const nomeCliente = dados.nome || $('Code').all()[index].json.nome;
  const emailCliente = dados.email || $('Code').all()[index].json.email;

  // 3. Normaliza o e-mail: remove espaços em branco e coloca tudo em minúsculas
  const emailNormalizado = String(emailCliente).trim().toLowerCase();

  return {
    json: {
      destinatario: emailNormalizado, // ou coloque o seu e-mail pessoal aqui para testar o recebimento!
      cliente_nome: nomeCliente,
      assunto: `Personalizado para você: Oportunidades de Investimento - ${nomeCliente}`,
      corpo_email: textoIA
    }
  };
});
